from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()


@app.get("/limited", rate_limit="50/minute")
def limited():
    return {"ok": True}


@app.get("/unlimited")
def unlimited():
    return {"ok": True}


client = TestClient(app)


def test_limited_endpoint():
    response = client.get("/limited")
    assert response.status_code == 200, response.text
    assert response.json() == {"ok": True}


def test_unlimited_endpoint():
    response = client.get("/unlimited")
    assert response.status_code == 200, response.text
    assert response.json() == {"ok": True}


def test_rate_limit_appears_in_openapi():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    schema = response.json()
    assert schema["paths"]["/limited"]["get"]["x-rate-limit"] == "50/minute"


def test_rate_limit_absent_when_not_set():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    schema = response.json()
    assert "x-rate-limit" not in schema["paths"]["/unlimited"]["get"]
